vec4 transition(vec2 uv) {
  float jitter = (fract(sin(dot(vec2(floor(uv.y * 18.0), progress), vec2(12.9898, 78.233))) * 43758.5453) - 0.5) * strength * (1.0 - abs(progress - 0.5) * 2.0);
  vec2 warped = uv + vec2(jitter, 0.0);
  vec4 a = getFromColor(warped);
  vec4 b = getToColor(uv - vec2(jitter, 0.0));
  float m = smoothstep(progress - 0.18, progress + 0.18, uv.x + jitter);
  return mix(a, b, m);
}
